result = [3, 3, 2, 3, 3, 3, 3, 3, 3, 3, 3, 3, 1, 0, 2, 1, 0, 2, 2, 2, 0, 1, 0, 1]
# Check the sums
subsets = {0: [], 1: [], 2: [], 3: []}
for i, subset_id in enumerate(result):
    subsets[subset_id].append(i + 1)

for subset_id, elements in subsets.items():
    print(f"Subset {subset_id}: {elements}, Sum: {sum(elements)}")
